// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.Arrays;

/**
 * Nanoseconds per physical feature, fixed for the process. It turns a {@link LmdbNativeCostQuote} into a time interval
 * that candidates of different families can be compared on. The default coefficients are the machine prior the adaptive
 * model used to start from; milestone M4 replaces them with a calibrated, checked-in vector.
 */
final class LmdbNativeStaticPrior {

	static final LmdbNativeStaticPrior DEFAULT = new LmdbNativeStaticPrior(
			LmdbNativeMachineCostModel.defaultPriorCoefficients());

	private final double[] coefficients;

	LmdbNativeStaticPrior(double[] coefficients) {
		if (coefficients.length != LmdbNativeCostVector.Feature.values().length) {
			throw new IllegalArgumentException("one coefficient per feature expected");
		}
		this.coefficients = coefficients.clone();
	}

	/**
	 * Speed-up a parallel variant achieves over its serial tier, as measured by the regret harness on 3000-person FOAF
	 * stores (2026-11-02, medians over 15 to 42 decisions): row kernels 1.0 to 1.3, parallel pipelines 1.8, parallel
	 * aggregates 0.6 to 0.7 (slower than serial). Dividing by the worker count (15 here) overstated the gain by an
	 * order of magnitude and made the parallel tier win every priced decision. The 30000-person run decides whether
	 * these grow with input size; until then the measured medians stand.
	 */
	static double measuredParallelSpeedup(String tag, int workers) {
		String base = LmdbNativeCandidate.baseId(tag);
		if (base.contains("Aggregate") || base.contains("Aggregation")) {
			// parallel aggregates measured 0.38 to 0.70 of serial speed at both 3000 and 15000 people
			return 0.5D;
		}
		// Row kernels and pipelines: at 15000 people a 3 s serial join ran in 460 ms in parallel (6.5x on fifteen
		// workers) while sub-50 ms joins gained nothing; the per-worker start below carries the fixed part, so the
		// streaming part scales by about 0.44 of the worker count.
		return Math.max(1D, 0.44D * workers);
	}

	/**
	 * Fixed cost a strategy pays before its first row beyond the common query overhead, in nanoseconds, measured by the
	 * regret harness on 3000-person stores (2026-11-02) as the minimum median of decisions with at most twenty output
	 * rows, less the 50 µs the cheapest strategy pays: compilation for the Janino aggregate, factor-tree and
	 * factorized-tail construction, kernel lowering for the IR aggregates. Strategies not listed pay nothing extra.
	 */
	static double fixedNanos(String tag) {
		return switch (LmdbNativeCandidate.baseId(tag)) {
		case LmdbNativeAttemptMetrics.PATH_JANINO_AGGREGATE -> 2_500_000D;
		case LmdbNativeAttemptMetrics.PATH_FACTORIZED_TAIL -> 2_300_000D;
		case LmdbNativeAttemptMetrics.PATH_PACKED_FTREE_AGGREGATE -> 4_900_000D;
		case LmdbNativeAttemptMetrics.PATH_ORDERED_DISTINCT_GROUPS -> 3_900_000D;
		case LmdbNativeAttemptMetrics.PATH_WILDCARD_PREDICATE_REDUCED -> 2_700_000D;
		case LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_WILDCARD,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_WILDCARD_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_ORDERED_SINGLE_PATTERN_GROUPS ->
			600_000D;
		// compiled and interpreted aggregate tiers measured 0.95 of each other end to end at both sizes
		case LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_INTERPRETED, LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE ->
			200_000D;
		case LmdbNativeAttemptMetrics.PATH_INDEXED_COUNT -> 140_000D;
		case LmdbNativeAttemptMetrics.PATH_ADJACENCY_AGGREGATE, LmdbNativeAttemptMetrics.PATH_PREFIX_RUN_GROUPS ->
			90_000D;
		default -> 0D;
		};
	}

	double coefficient(LmdbNativeCostVector.Feature feature) {
		return coefficients[feature.ordinal()];
	}

	/** The time interval of a feature vector, in nanoseconds; an unbounded count gives an unbounded ceiling. */
	LmdbNativeWork price(LmdbNativeCostVector vector) {
		double low = vector.dotLow(coefficients);
		double high = vector.dotHigh(coefficients);
		for (LmdbNativeCostVector.Feature feature : LmdbNativeCostVector.Feature.values()) {
			if (vector.high(feature) >= LmdbNativeCostQuote.UNBOUNDED_COUNT) {
				return LmdbNativeWork.atLeast(low);
			}
		}
		return LmdbNativeWork.between(low, Math.max(low, high));
	}

	/** The expected time of a feature vector, in nanoseconds. */
	double expected(LmdbNativeCostVector vector) {
		return vector.dotExpected(coefficients);
	}

	@Override
	public String toString() {
		return "LmdbNativeStaticPrior" + Arrays.toString(coefficients);
	}
}
